<?php include 'config.php'; if(!isLoggedIn()){header('Location: login.php');exit;} $uid=$_SESSION['user_id']; $u=$conn->query("SELECT * FROM users WHERE user_id=$uid")->fetch_assoc(); $orders=$conn->query("SELECT * FROM orders WHERE user_id=$uid"); ?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Profile</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'nav.php'; ?><section class="page"><h1>My Profile</h1><div class="table-box"><p>Name: <?=clean($u['full_name'])?></p><p>Email: <?=clean($u['email'])?></p><p>Phone: <?=clean($u['phone'])?></p></div><br><div class="table-box"><h2>Orders</h2><table><tr><th>ID</th><th>Total</th><th>Status</th></tr><?php while($o=$orders->fetch_assoc()): ?><tr><td><?=$o['order_id']?></td><td>$<?=$o['total_amount']?></td><td><?=$o['status']?></td></tr><?php endwhile; ?></table></div></section></body></html>